#pragma once

#include <stdexcept>
#include <string>

// NotFinished: thrown by every TODO stub, and by WindowDriver when the
// window has no control with the name the check asks for. LabCheck catches
// it and prints "Not finished yet." C# uses NotImplementedException for this.
// Do not edit this file.
struct NotFinished : std::logic_error
{
    // A stub that has not been written yet.
    NotFinished() : std::logic_error("Not finished yet.")
    {
    }

    // A missing piece, with a message that says which one.
    explicit NotFinished(const std::string& message) : std::logic_error(message)
    {
    }
};
